head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setFixedRow]<br/>GridView 컴포넌트의 fixedRow 속성을 설정합니다.",
    "validation" : [
        "fixedRowNum(필수) 파라미터로 세로 스크롤 되지 않고 고정으로 표시할 Row 의 갯수를 설정할 수 있어야 합니다.",
        "fixedRowNum 을 0 으로 설정 시 Row 를 고정하지 않아야 합니다.",
        "setFixedRow() 메소드로 fixedRow 속성값을 변경하면 고정으로 표시되던 Row 는 다음번 스크롤 시 갱신되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성 (10행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 10);

    // target 생성
    await $c.gcm.createBasicGridView(cList);

    // 세로 스크롤 생성을 위해 height 변경
    target1.setStyle("height", "220px");
}



scwin.btn_setFixedRow_onclick = function () {
    let fixedRowNum = Number(par_fixedRowNum.getText());

    target1.setFixedRow(fixedRowNum);
    wf_body_bottom.getObj("scwin").setReturnValue("setFixedRow(" + fixedRowNum + ")");
}



scwin.btn_getFixedRow_onclick = function () {
    let rtn = target1.getFixedRow();
    wf_body_bottom.getObj("scwin").setReturnValue("getFixedRow() : " + rtn);

    let targetElement = document.querySelector('tr[class*="grid_body_row w2grid_fixedRow"]');
    if (targetElement) {
        let textContent = targetElement.textContent;
        wf_body_bottom.getObj("scwin").setReturnValue("fixed row 의 값 : " + textContent);
    }
}
